annot be stolen through the attack method which caused this change. *   See also the following blog posts for details: * *  - https://embracethered.com/blog/posts/2024/cookie-theft-in-2024-and-what-todo/ *  - https://mango.pdf.zone/stealing-chrome-cookies-without-a-password/ *  - https://developer.chrome.com/blog/chrome-for-testing *      - https://github.com/GoogleChromeLabs/chrome-for-testing#json-api-endpoints *  - https://chromium.googlesource.com/chromium/src/+/HEAD/docs/user_data_dir.md *  - https://docs.google.com/document/d/1XJvxyqAQjhPfJ0rX84PjfXXb5sBx3m8DXzMxR0ipQNs/edit?tab=t.0#heading=h.j7abhcnnl3y7 *  - https://github.com/natkuhn/Chrome-Debug/ */class DesktopChromium extends AbstractDriver{    /**     * The default port for thr browser `--remote-debugging-port` value.     *     * @var int     */    public const DEFAULT_PORT = 9222;    /**     * The default timeout for requests to the endpoint.     */    public const DEFAULT_TIMEOUT = 10;    /**     * The default amount of seconds to wait before returning from process start/stop calls.     *     * @var int     */    public const DEFAULT_DELAY = 0;    private readonly Process $process;    public readonly string $browser;    public function __construct(        string              $browser,        string              $file,        int                 $port        = self::DEFAULT_PORT,        bool                $debug       = false,        int                 $timeout     = self::DEFAULT_TIMEOUT,        public readonly int $delay       = self::DEFAULT_DELAY,    ) {        parent::__construct($file, $port, $debug, $timeout);        $this->browser = \escapeshellcmd($browser);        // TODO: Make this available as debug argument (`--profile-name`).        $profileName = 'cruserdata';        if (Platform::isPhar()) {            $userDataDir = \getcwd() . \DIRECTORY_SEPARATOR . $profileName;        } else {            $userDataDir = __DIR__                . \DIRECTORY_SEPARATOR . '..'                . \DIRECTORY_SEPARATOR . '..'                . \DIRECTORY_SEPARATOR . $profileName;        }        $userDataDir = \escapeshellarg($userDataDir);        if (Platform::isWindows()) {            // Call the given application path on Windows.            $command = ["{$this->browser}", "--remote-debugging-port={$this->port}", "--user-data-dir={$userDataDir}"];        } elseif (Platform::isMacOs()) {            // On Mac, we can use `open` to address a given application (`.app`).            $command = ['open', '-n', "{$this->browser}", '--args', "--remote-debugging-port={$this->port}", "--user-data-dir={$userDataDir}"];        } else {            // Call the given application path on Linux.            $command = ["{$this->browser}", "--remote-debugging-port={$this->port}", "--user-data-dir={$userDataDir}"];        }        $this->process = new Process($command);    }    public function start(): void    {        $console = $this->getConsole();        $console->writeln(' ==> ' . __METHOD__ . ':', OutputInterface::VERBOSITY_DEBUG);        $console->comment("Starting `{$this->browser}` background process...");        $console->progressStart(1);        $this->process->start();        $console->progressFinish();        if (0 < $this->delay) {            $console->writeln("Waiting for {$this->delay} seconds...", OutputInterface::VERBOSITY_VERY_VERBOSE);            \sleep($this->delay);        }        $console->writeln(' ==> ' . __METHOD__ . ': Done.', OutputInterface::VERBOSITY_DEBUG);    }    public function stop(): void    {        $console = $this->getConsole();        $console->writeln(' ==> ' . __METHOD__ . ':', OutputInterface::VERBOSITY_DEBUG);        $console->comment("Stopping `{$this->browser}` background process...");        $console->progressStart(1);        $this->process->stop();        $this->process->wait();        $console->progressFinish();        if ($this->debug) {            $combinedProcessOutput = \array_filter(                \array_map(                    static fn(string $line): string => "< {$line}",                    \array_merge(                        \explode(\PHP_EOL, $this->process->getOutput()),                        \explode(\PHP_EOL, $this->process->getErrorOutput()),                    )                )            );            $console->writeln($combinedProcessOutput);            $console->newLine();        }        if (0 < $this->delay) {            $console->writeln("Waiting for {$this->delay} seconds...", OutputInterface::VERBOSITY_VERY_VERBOSE);            \sleep($this->delay);        }        $console->writeln(' ==> ' . __METHOD__ . ': Done.', OutputInterface::VERBOSITY_DEBUG);    }    public function getUrl(): string    {        return "http://localhost:{$this->port}/json/list";    }    protected function getShellCommand(): ?string    {        return $this->browser;    }}